import{_ as p,a0 as r,w as u,s as i,ao as a,I as o,x as e,a1 as n,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"修復 Shell 腳本在 Ubuntu 中的默認打開方式 | LCTT x X-CMD","titleTemplate":false,"description":"修復 Shell 腳本在 Ubuntu 中的默認打開方式 | LCTT (201511) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"修復 Shell 腳本在 Ubuntu 中的默認打開方式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"修復 Shell 腳本在 Ubuntu 中的默認打開方式 | LCTT (201511) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201511/20151007-Fix-Shell-Script-Opens-In-Text Editor In Ubuntu","title":"修復 Shell 腳本在 Ubuntu 中的默認打開方式","tag":"201511","desc":""},"relativePath":"201511/20151007-Fix-Shell-Script-Opens-In-Text Editor In Ubuntu.md","filePath":"[post].md"}'),d={name:"201511/20151007-Fix-Shell-Script-Opens-In-Text Editor In Ubuntu.md"};function h(f,t,m,b,x,g){const s=r("Link");return u(),i("div",null,[t[13]||(t[13]=a('<h1 id="修復-shell-腳本在-ubuntu-中的默認打開方式" tabindex="-1">修復 Shell 腳本在 Ubuntu 中的默認打開方式 <a class="header-anchor" href="#修復-shell-腳本在-ubuntu-中的默認打開方式" aria-label="Permalink to “修復 Shell 腳本在 Ubuntu 中的默認打開方式”">​</a></h1><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/10/Run-Shell-Script-on-Double-Click.jpg" alt=""></p><p>當你雙擊一個腳本（.sh文件）的時候，你想要做的是什麼？通常的想法是執行它。但是在Ubuntu下面卻不是這樣，或者我應該更確切地説是在Files（Nautilus）中。你可能會瘋狂地大叫“運行文件，運行文件”，但是文件沒有運行而是用Gedit打開了。</p><p>我知道你也許會説文件有可執行權限麼？我會説是的。腳本有可執行權限但是當我雙擊它的時候，它還是用文本編輯器打開了。我不希望這樣，如果你遇到了同樣的問題，我想你也許也想要這樣。</p><p>我知道你或許已經被建議在終端下面執行，我知道這個可行，但是這不是一個在GUI下不能運行的藉口是麼？</p><p>這篇教程中，我們會看到<strong>如何在雙擊後運行shell腳本。</strong></p><h4 id="修復在ubuntu中shell腳本用文本編輯器打開的方式" tabindex="-1">修復在Ubuntu中shell腳本用文本編輯器打開的方式 <a class="header-anchor" href="#修復在ubuntu中shell腳本用文本編輯器打開的方式" aria-label="Permalink to “修復在Ubuntu中shell腳本用文本編輯器打開的方式”">​</a></h4><p>shell腳本用文件編輯器打開的原因是Files（Ubuntu中的文件管理器）中的默認行為設置。在更早的版本中，它或許會詢問你是否運行文件或者用編輯器打開。默認的行為在新的版本中被修改了。</p><p>要修復這個，進入文件管理器，並在菜單中點擊<strong>選項</strong>：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/10/execute-shell-program-ubuntu-1.png" alt=""></p><p>接下來在<strong>文件選項（Files Preferences）</strong>中進入<strong>行為（Behavior）</strong>標籤中，你會看到<strong>可執行的文本文件（Executable Text Files）</strong>選項。</p><p>默認情況下，它被設置成“在打開時顯示文本文件（View executable text files when they are opend）”。我建議你把它改成“每次詢問（Ask each time）”，這樣你可以選擇是執行還是編輯了，當然了你也可以選擇“在打開時雲可執行文本文件（Run executable text files when they are opend）”。你可以自行選擇。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/10/execute-shell-program-ubuntu-2.png" alt=""></p><p>我希望這個貼士可以幫你修復這個小“問題”。歡迎提出問題和建議。</p><hr>',15)),o("p",null,[t[1]||(t[1]=e("via: ",-1)),n(s,{href:"http://itsfoss.com/shell-script-opens-text-editor/"},{default:l(()=>[...t[0]||(t[0]=[e("http://itsfoss.com/shell-script-opens-text-editor/",-1)])]),_:1})]),o("p",null,[t[5]||(t[5]=e("作者：",-1)),n(s,{href:"http://itsfoss.com/author/abhishek/"},{default:l(()=>[...t[2]||(t[2]=[e("Abhishek",-1)])]),_:1}),t[6]||(t[6]=e(" 譯者：",-1)),n(s,{href:"https://github.com/geekpi"},{default:l(()=>[...t[3]||(t[3]=[e("geekpi",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),n(s,{href:"https://github.com/wxy"},{default:l(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=e("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創翻譯，",-1)),n(s,{href:"http://linux.cn/"},{default:l(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const U=p(d,[["render",h]]);export{C as __pageData,U as default};
